{
  description = "A CI-optimized automation script to run an x86_64 guest kernel hearbeat check inside QEMU";

  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/master";
  };

  outputs = { self, nixpkgs }:
    let
      host = import nixpkgs { system = "aarch64-darwin"; };

      # Pull pre-compiled kernel artifact from the cache
      guestLinuxPkgs = (import nixpkgs { system = "x86_64-linux"; }).linuxPackages;
      kernel_dir = guestLinuxPkgs.kernel;

      # Pull pre-compiled static busybox directly from Nix cache
      guestStaticPkgs = import nixpkgs { system = "x86_64-linux"; };
      busybox_static = guestStaticPkgs.pkgsStatic.busybox;
    in {
      packages.aarch64-darwin.default = host.writeTextFile {
        name = "qemu-boot-busybox-kernel-heartbeat";
        executable = true;
        destination = "/bin/qemu-boot-busybox-kernel-heartbeat";
        text = ''
#!${host.stdenv.shell}
BASE_DIR=$(pwd)
LOG_PATH="$BASE_DIR/test.log"
ERR_LOG="$BASE_DIR/qemu_error.log"

cleanup() {
  echo "Cleaning workspace artifacts..."
  rm -rf "$BASE_DIR/tmp_initrd"
  rm -f "$BASE_DIR/initrd.cpio"
  rm -f "$LOG_PATH" "$ERR_LOG"
  echo "Workspace clean."
}

trap cleanup EXIT INT TERM

echo "--- Step 1: Building minimal initrd ---"
mkdir -p "$BASE_DIR/tmp_initrd/bin"
mkdir -p "$BASE_DIR/tmp_initrd/proc" "$BASE_DIR/tmp_initrd/sys" "$BASE_DIR/tmp_initrd/dev"
mkdir -p "$BASE_DIR/tmp_initrd/etc"

cp "${busybox_static}/bin/busybox" "$BASE_DIR/tmp_initrd/bin/busybox"
chmod +x "$BASE_DIR/tmp_initrd/bin/busybox"
ln -sf busybox "$BASE_DIR/tmp_initrd/bin/sh"

cp "${busybox_static}/bin/busybox" "$BASE_DIR/tmp_initrd/init"
chmod +x "$BASE_DIR/tmp_initrd/init"

# Direct command calls in inittab (No shell used)
cat <<EOF > "$BASE_DIR/tmp_initrd/etc/inittab"
::sysinit:/bin/busybox mount -t proc proc /proc
::sysinit:/bin/busybox mount -t sysfs sysfs /sys
::sysinit:/bin/busybox mount -t devtmpfs devtmpfs /dev
::sysinit:/bin/busybox cat /proc/version
::sysinit:/bin/busybox cat /proc/cpuinfo
::sysinit:/bin/busybox cat /proc/meminfo
::sysinit:/bin/busybox poweroff -f
EOF

# Pack the directory tree entries
cd "$BASE_DIR/tmp_initrd"
find . ! -name "." | ${host.cpio}/bin/cpio -oH newc > "$BASE_DIR/initrd.cpio"
cd "$BASE_DIR"

echo "--- Step 2: Running Automated QEMU Instance ---"
> "$LOG_PATH"

${host.qemu}/bin/qemu-system-x86_64 -cpu max -kernel ${kernel_dir}/bzImage -initrd ./initrd.cpio -nographic -display none -no-reboot -serial file:"$LOG_PATH" -append "console=ttyS0 init=/init panic=-1" -m 512M 2> "$ERR_LOG"

echo "--- Step 3: Verifying Results ---"
if [ -s "$LOG_PATH" ]; then
  echo "--- Captured Guest Logs ---"
  cat -n "$LOG_PATH"

  # Verify that the specific system files were read successfully
  if grep -q "Linux version" "$LOG_PATH" && grep -q "model name" "$LOG_PATH" && grep -q "MemTotal" "$LOG_PATH"; then
    echo "CI STATUS: SUCCESS"
    exit 0
  else
    echo "CI STATUS: FAILURE (Diagnostics missing from log)"
    exit 1
  fi
else
  echo "CI STATUS: ERROR (Empty Log Layout)"
  [ -f "$ERR_LOG" ] && cat -n "$ERR_LOG"
  exit 1
fi
        '';
      };
    };
}

# Follow the guidance at https://github.io
{
  description = "WASM Kinetic Art Generator";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    rust-overlay.url = "github:oxalica/rust-overlay";
  };

  outputs = { self, nixpkgs, rust-overlay }:
    let
      system = "aarch64-darwin";
      pkgs = import nixpkgs {
        inherit system;
        overlays = [ (import rust-overlay) ];
      };

      rustToolchain = pkgs.rust-bin.stable.latest.default.override {
        targets = [ "wasm32-unknown-unknown" ];
      };
    in {
      packages.${system} = let
        buildWorkspace = pkgs.runCommand "art-workspace" {
          nativeBuildInputs = [ pkgs.coreutils ];
        } ''
          mkdir -p $out

          # --- WASM Engine Source ---
          # Dimension constants updated to 1280x720 HD for sharp scaling performance
          cat << 'EOF' > $out/engine.rs
          static mut TIME: f32 = 0.0;
          const WIDTH: usize = 1280;
          const HEIGHT: usize = 720;
          static mut BUFFER: [u32; WIDTH * HEIGHT] = [0xFF050505; WIDTH * HEIGHT];

          #[no_mangle]
          pub extern "C" fn get_buffer_ptr() -> *const u32 {
              unsafe { std::ptr::addr_of!(BUFFER) as *const u32 }
          }

          #[no_mangle]
          pub extern "C" fn render_frame() {
              unsafe {
                  TIME += 0.015;

                  let buffer_ptr = std::ptr::addr_of_mut!(BUFFER) as *mut u32;

                  for offset in 0..(WIDTH * HEIGHT) {
                      let p = *buffer_ptr.add(offset);
                      let r = ((p & 0xFF) as f32 * 0.92) as u32;
                      let g = (((p >> 8) & 0xFF) as f32 * 0.92) as u32;
                      let b = (((p >> 16) & 0xFF) as f32 * 0.92) as u32;
                      *buffer_ptr.add(offset) = r | (g << 8) | (b << 16) | 0xFF000000;
                  }

                  let cx = (WIDTH / 2) as f32;
                  let cy = (HEIGHT / 2) as f32;

                  // Radius parameters optimized to fill a widescreen aspect ratio
                  let r_outer = 240.0;
                  let r_inner = 150.0;
                  let d = 130.0 + TIME.sin() * 60.0;

                  for i in 0..1000 { // Increased particle density for widescreen definition
                      let t = (i as f32) * 0.05 + TIME;
                      let ratio = (r_outer - r_inner) / r_inner;
                      let base_x = (r_outer - r_inner) * t.cos() + d * (ratio * t).cos();
                      let base_y = (r_outer - r_inner) * t.sin() - d * (ratio * t).sin();

                      let wave_mod_x = (t * 7.0 + TIME * 2.5).sin() * 40.0;
                      let wave_mod_y = (t * 5.0 - TIME * 3.1).cos() * 40.0;

                      let px = (cx + base_x + wave_mod_x) as i32;
                      let py = (cy + base_y + wave_mod_y) as i32;

                      let r_color = ((t.sin() * 127.0) + 128.0) as u32;
                      let g_color = (((t + 2.0).sin() * 127.0) + 128.0) as u32;
                      let b_color = (((TIME * 0.5).cos() * 100.0) + 155.0) as u32;
                      let packed_color = r_color | (g_color << 8) | (b_color << 16) | 0xFF000000;

                      for dx in 0..2 {
                          for dy in 0..2 {
                              let target_x = px + dx;
                              let target_y = py + dy;
                              if target_x >= 0 && target_x < WIDTH as i32 && target_y >= 0 && target_y < HEIGHT as i32 {
                                  let offset = (target_y as usize * WIDTH) + target_x as usize;
                                  *buffer_ptr.add(offset) = packed_color;
                              }
                          }
                      }
                  }
              }
          }
          EOF

          ${rustToolchain}/bin/rustc --target wasm32-unknown-unknown --crate-type cdylib -C opt-level=z -C lto=fat $out/engine.rs -o $out/engine.wasm

          WASM_BASE64=$(base64 $out/engine.wasm | tr -d '\n')

          # --- Launcher Source ---
          # CSS update: Made the canvas element take up 100vw and 100vh with an absolute stretch layout
          cat << EOF > $out/launcher.rs
          use std::{io::{Read, Write}, net::TcpListener, process::Command};
          fn main() {
              let html_content = "<!DOCTYPE html><html><head><title>WASM Kinetic Art</title><style>html,body{margin:0;padding:0;overflow:hidden;background:#050505;width:100%;height:100%;}canvas{width:100vw;height:100vh;display:block;object-fit:cover;}</style></head><body><canvas id=\"canvas\" width=\"1280\" height=\"720\"></canvas><script>const base64 = '$WASM_BASE64'; const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0)); WebAssembly.instantiate(bytes).then(({instance}) => { const { memory, get_buffer_ptr, render_frame } = instance.exports; const canvas = document.getElementById('canvas'); const ctx = canvas.getContext('2d'); const imgData = ctx.createImageData(1280, 720); const u8Buffer = new Uint8Array(memory.buffer, get_buffer_ptr(), 1280 * 720 * 4); const draw = () => { render_frame(); imgData.data.set(u8Buffer); ctx.putImageData(imgData, 0, 0); requestAnimationFrame(draw); }; draw(); });</script></body></html>";

              let response = format!("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}", html_content.len(), html_content);
              let favicon_404 = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";

              let listener = TcpListener::bind("127.0.0.1:8888").expect("Failed to bind to port 8888");
              println!("[Server] In-memory server running at http://127.0.0.1:8888");

              Command::new("open").arg("http://127.0.0.1:8888").spawn().expect("Failed to open browser");

              for stream in listener.incoming() {
                  if let Ok(mut stream) = stream {
                      let mut buffer = [0; 1024];
                      if let Ok(bytes_read) = stream.read(&mut buffer) {
                          let request_str = String::from_utf8_lossy(&buffer[..bytes_read]);
                          if request_str.contains("GET /favicon.ico") {
                              let _ = stream.write_all(favicon_404.as_bytes());
                          } else {
                              let _ = stream.write_all(response.as_bytes());
                          }
                          let _ = stream.flush();
                      }
                  }
              }
          }
          EOF
        '';

        launcher = pkgs.stdenv.mkDerivation {
          pname = "wasm-art-launcher"; version = "1.3.0"; src = buildWorkspace;
          nativeBuildInputs = [ rustToolchain ];
          buildPhase = "rustc -O launcher.rs -o wasm-art-launcher";
          installPhase = "mkdir -p $out/bin && cp wasm-art-launcher $out/bin/";
        };

      in {
        default = launcher;
      };

      devShells.${system}.default = pkgs.mkShell { buildInputs = [ rustToolchain ]; };
    };
}
